CREATE TABLE IF NOT EXISTS pitlane.artifacts(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,project_id uuid NOT NULL,job_id uuid NOT NULL,lease_epoch bigint NOT NULL,object_key text NOT NULL UNIQUE,digest text NOT NULL CHECK(length(digest)=64),bytes bigint NOT NULL CHECK(bytes>=0),content_type text NOT NULL,state text NOT NULL CHECK(state IN('hash_verified','published')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(job_id,tenant_id,project_id) REFERENCES pitlane.jobs(id,tenant_id,project_id),UNIQUE(id,tenant_id,project_id));
CREATE TABLE IF NOT EXISTS pitlane.receipt_versions(id uuid PRIMARY KEY,receipt_id uuid NOT NULL,tenant_id uuid NOT NULL,project_id uuid NOT NULL,job_id uuid NOT NULL,payload jsonb NOT NULL,digest text NOT NULL CHECK(length(digest)=64),artifact_id uuid NOT NULL,supersedes_id uuid REFERENCES pitlane.receipt_versions(id),issued_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,FOREIGN KEY(job_id,tenant_id,project_id) REFERENCES pitlane.jobs(id,tenant_id,project_id),FOREIGN KEY(artifact_id,tenant_id,project_id) REFERENCES pitlane.artifacts(id,tenant_id,project_id),UNIQUE(id,tenant_id,project_id));
CREATE UNIQUE INDEX IF NOT EXISTS receipt_original ON pitlane.receipt_versions(job_id) WHERE supersedes_id IS NULL;
CREATE TABLE IF NOT EXISTS pitlane.receipt_heads(receipt_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,project_id uuid NOT NULL,version_id uuid NOT NULL,FOREIGN KEY(version_id,tenant_id,project_id) REFERENCES pitlane.receipt_versions(id,tenant_id,project_id));
DO $$ DECLARE n text; BEGIN FOREACH n IN ARRAY ARRAY['artifacts','receipt_versions','receipt_heads'] LOOP EXECUTE format('ALTER TABLE pitlane.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('DROP POLICY IF EXISTS scoped_read ON pitlane.%I',n);EXECUTE format('CREATE POLICY scoped_read ON pitlane.%I FOR SELECT USING(pitlane.can_project(tenant_id,project_id))',n);EXECUTE format('GRANT SELECT ON pitlane.%I TO pitlane_web',n);END LOOP; END $$;
